/**
 * @file ui_assets_sel.h
 * @brief Pick the precomputed asset set that matches the panel.
 *
 * The 320x240 assets live in ui_assets.h/.c (generated by
 * scripts/gen_ui_assets.py, unchanged since the original panel); the 480x320
 * set is generated into ui_assets_480.h/.c with the larger row, title and
 * icon geometry. Exactly one of the two is compiled and included.
 */

#ifndef UI_ASSETS_SEL_H
#define UI_ASSETS_SEL_H

#include "ui_layout.h"

#if UI_LAYOUT_LARGE
#include "ui_assets_480.h"
#else
#include "ui_assets.h"
#endif

#endif /* UI_ASSETS_SEL_H */
